# f: bbox of non-bg; fill bbox border cells that are bg with color 2
def f(g):
    g=[r[:] for r in g]; h=len(g); w=len(g[0])
    cells=[(i,j) for i in range(h) for j in range(w) if g[i][j]!=g[0][0]]
    r0=min(i for i,_ in cells); r1=max(i for i,_ in cells); c0=min(j for _,j in cells); c1=max(j for _,j in cells)
    out=g
    for i in (r0,r1):
        for j in range(c0,c1+1):
            if out[i][j]==g[0][0]: out[i][j]=2
    for j in (c0,c1):
        for i in range(r0,r1+1):
            if out[i][j]==g[0][0]: out[i][j]=2
    return out
